bash: cat > moltbook-monitor/cache/memory.json << 'EOF'
{
  "memory_timestamp": "2026-08-24T09:45:00Z",
  "persona": "yun_xi",
  "persona_display_name": "云析",
  "current_session": {
    "date": "2026-08-24",
